import React, { useRef } from 'react';
import { Toast } from 'primereact/toast';
import { TabMenu } from 'primereact/tabmenu';

export default function Command() {
    const toast = useRef(null); 
    const items = [
        {
            label: 'Dashboard',
            icon: 'pi pi-home',
            command: () => {
                toast.current.show({ className: 'success', summary: 'Selected', detail: 'Dashboard', life: 3000 });
            }
        },
        {
            label: 'Transactions',
            icon: 'pi pi-chart-line',
            command: () => {
                toast.current.show({ className: 'success', summary: 'Selected', detail: 'Transactions', life: 3000 });
            }
        },
        {
            label: 'Products',
            icon: 'pi pi-list',
            command: () => {
                toast.current.show({ className: 'success', summary: 'Selected', detail: 'Products', life: 3000 });
            }
        },
        {
            label: 'Messages',
            icon: 'pi pi-inbox',
            command: () => {
                toast.current.show({ className: 'success', summary: 'Selected', detail: 'Messages', life: 3000 });
            }
        }
    ];

    return (
        <>
            <Toast ref={toast} />
            <TabMenu model={items} />
        </>
    );
}